// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(this)); }
    function testFuzz_property(uint256 amount, address sender) public {
        vm.assume(amount == c.MinDeposit());
        vm.assume(sender != address(0));
        uint256 balBefore = c.balances(sender);
        vm.deal(sender, amount);
        vm.prank(sender);
        c.Deposit{value: amount}();
        uint256 balAfter = c.balances(sender);
        assertTrue(balAfter == balBefore);
    }
}
